package ai.decisionos.aside;
import android.app.*;import android.os.Bundle;import android.widget.*;import org.json.*;import java.util.*;
/** Qwen shares the native goal browser and fixed DOM readers; no arbitrary JS/click/write tool. */
public final class GoalAgentActivity extends GoalDiscoveryActivity {
 GoalAgentRelay relay;TextView remoteStatus;String observationId="",observationUrl="",selectedUrl="";int observationGeneration=-1;JSONArray observed=new JSONArray();final Set<String> sources=new HashSet<>();
 boolean autoLoad(){return false;}
 public void onCreate(Bundle b){String id=getIntent().getStringExtra("goal_id");try(GoalStore s=new GoalStore(this)){JSONObject g=s.goal(id);getIntent().putExtra("provider","youtube");getIntent().putExtra("query",GoalRules.query(g.optString("character"),g.optBoolean("motivation",true),g.optBoolean("information",true),g.optString("topic"),g.optString("language","ko")));}catch(Exception e){finish();return;}super.onCreate(b);if(web==null)return;
  LinearLayout panel=card();note(panel,"Qwen은 연결된 서버에서 실행돼. 목표 주제와 공개 검색 결과를 모델 서버로 보내며, 로그인·주문·신청·메시지는 실행하지 않아. 화면을 벗어나면 연결을 끊어.");remoteStatus=txt("Qwen 연결 전",14,MUTED,false);panel.addView(remoteStatus);relay=new GoalAgentRelay(this,this::command,text->remoteStatus.setText(text));action(panel,"Qwen 원격 연결",()->{EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(129);e.setHint("https://서버:포트|연결키|인증서 지문");new AlertDialog.Builder(this).setTitle("Qwen 목표 탐색 연결").setView(e).setNegativeButton("취소",null).setPositiveButton("연결",(d,w)->{try{relay.connect(e.getText().toString());}catch(Exception ex){remoteStatus.setText("연결 실패 · 형식을 확인해줘.");}}).show();});action(panel,"Qwen 연결 끊기",()->{relay.stop();remoteStatus.setText("연결을 끊었어.");});scroll.post(()->scroll.fullScroll(android.view.View.FOCUS_DOWN));
 }
 static boolean sameSource(String a,String b){try{android.net.Uri x=android.net.Uri.parse(a),y=android.net.Uri.parse(b);String hx=x.getHost(),hy=y.getHost();return GoalRules.safe(a)&&GoalRules.safe(b)&&hx!=null&&hy!=null&&hx.replaceFirst("^(www|m)\\.","").equals(hy.replaceFirst("^(www|m)\\.",""))&&Objects.equals(x.getPath(),y.getPath())&&(Objects.equals(x.getQuery(),y.getQuery())||hx.endsWith("youtube.com")&&"/watch".equals(x.getPath())&&x.getQueryParameter("v")!=null&&Objects.equals(x.getQueryParameter("v"),y.getQueryParameter("v")));}catch(Exception e){return false;}}
 static boolean supported(String p){return Arrays.asList("youtube","naverweb","11st","munto","kakaomap","realestate","kmooc","inflearn").contains(p);}
 JSONObject context()throws Exception{JSONObject g=store.goal(gid),out=new JSONObject();out.put("goal_id",gid);out.put("character",g.optString("character"));out.put("title",g.optString("title"));out.put("topic",g.optString("topic"));out.put("motivation",g.optBoolean("motivation",true));out.put("information",g.optBoolean("information",true));out.put("providers",new JSONArray(Arrays.asList("youtube","naverweb","11st","munto","kakaomap","realestate","kmooc","inflearn")));return out;}
 void invalidate(){generation++;latest=new JSONArray();observed=new JSONArray();observationId="";selectedUrl="";sources.clear();}
 void command(JSONObject cmd,GoalAgentRelay.Reply reply)throws Exception{String op=cmd.optString("op");JSONObject out=new JSONObject();
  if(op.equals("goal_open")){String character=cmd.optString("character");if(!Arrays.asList("fitness","love","grades","home").contains(character))throw new IllegalArgumentException("unsupported goal");JSONObject g=null;for(JSONObject row:store.goals())if(row.optString("character").equals(character)){g=row;break;}if(g==null){GoalRules.Preset p=GoalRules.preset(character);g=store.create(character,p.title,p.topic,0);}gid=g.optString("id");invalidate();web.stopLoading();web.loadUrl("about:blank");((TextView)body.getChildAt(0)).setText(GoalRules.preset(character).name+" · Qwen 탐색");remoteStatus.setText("Qwen 목표: "+g.optString("title"));out.put("state","goal_opened");out.put("goal",context());reply.send(out);return;}
  if(!gid.equals(cmd.optString("goal_id")))throw new IllegalArgumentException("goal context changed; open goal again");
  if(op.equals("goal_search")){JSONObject prefs=store.goal(gid);if(!prefs.optBoolean("motivation",true)&&!prefs.optBoolean("information",true))throw new IllegalArgumentException("goal discovery disabled by user");String p=cmd.optString("provider"),q=cmd.optString("query").trim();if(!supported(p)||q.isEmpty()||q.length()>100)throw new IllegalArgumentException("unsupported provider or query");provider=p;query=q;url=DiscoveryProviders.url(p,q);observationId="";observed=new JSONArray();selectedUrl="";latest=new JSONArray();web.loadUrl(url);remoteStatus.setText("Qwen 검색 · "+p+" · "+q);out.put("state","navigation_requested");out.put("goal_id",gid);out.put("provider",p);reply.send(out);return;}
  if(op.equals("goal_observe")){String current=web.getUrl();if(current==null||!GoalRules.safe(current)||current.toLowerCase(java.util.Locale.ROOT).matches(".*(login|signin|account|checkout).*"))throw new IllegalArgumentException("no allowed public page");if(failed||web.getProgress()<100){out.put("state","not_ready");reply.send(out);return;}final int seen=generation;final String seenGoal=gid;if(!selectedUrl.isEmpty()){if(!sameSource(current,selectedUrl))throw new IllegalArgumentException("selected source redirected; inspect search again");web.evaluateJavascript("JSON.stringify({title:document.title,url:location.href})",raw->{JSONObject result=new JSONObject();try{if(seen!=generation||!seenGoal.equals(gid)||!current.equals(web.getUrl()))throw new Exception();JSONObject page=new JSONObject(new JSONArray("["+raw+"]").getString(0));GoalStore.put(result,"state","source_observed");GoalStore.put(result,"goal_id",gid);GoalStore.put(result,"page",page);sources.add(current);}catch(Exception e){GoalStore.put(result,"error","page changed while observing");}reply.send(result);});return;}
   if(!DiscoveryProviders.searchMatches(provider,current,query))throw new IllegalArgumentException("not the requested search page");if(latest.length()==0){collect();out.put("state","not_ready");out.put("detail","result reader pending or no structured results; retry once or choose another provider");reply.send(out);return;}
   observed=new JSONArray();for(int n=0;n<latest.length()&&observed.length()<8;n++){JSONObject row=latest.getJSONObject(n);if(GoalRules.safe(row.optString("url"))){observed.put(new JSONObject(row.toString()));sources.add(row.optString("url"));}}observationId=UUID.randomUUID().toString();observationGeneration=generation;observationUrl=current;sources.add(current);out.put("state","results_observed");out.put("goal_id",gid);out.put("provider",provider);out.put("query",query);out.put("url",current);out.put("observation_id",observationId);out.put("items",observed);reply.send(out);return;
  }
  if(op.equals("goal_select")){int index=cmd.optInt("index",-1);if(!observationId.equals(cmd.optString("observation_id"))||observationId.isEmpty()||generation!=observationGeneration||!observationUrl.equals(web.getUrl())||index<0||index>=observed.length())throw new IllegalArgumentException("stale observation or invalid selection");selectedUrl=observed.getJSONObject(index).getString("url");if(!GoalRules.safe(selectedUrl))throw new IllegalArgumentException("source URL blocked");web.loadUrl(selectedUrl);out.put("state","navigation_requested");out.put("goal_id",gid);out.put("url",selectedUrl);reply.send(out);return;}
  if(op.equals("goal_report")){String summary=cmd.optString("summary").trim();JSONArray urls=cmd.optJSONArray("source_urls");if(summary.isEmpty()||summary.length()>3000||urls==null||urls.length()==0||urls.length()>12)throw new IllegalArgumentException("bounded summary and observed sources required");for(int n=0;n<urls.length();n++)if(!sources.contains(urls.getString(n)))throw new IllegalArgumentException("unobserved source");JSONObject patch=new JSONObject();patch.put("qwenSummary",summary);patch.put("qwenSources",urls);patch.put("qwenAt",java.time.Instant.now().toString());patch.put("qwenModel","Qwen3.8-27B-abliterated-AWQ-W4A16");store.patchGoal(gid,patch);remoteStatus.setText("Qwen 탐색 요약을 목표에 저장했어.");out.put("state","report_saved");out.put("goal_id",gid);reply.send(out);return;}
  throw new IllegalArgumentException("unsupported read-only goal action");
 }
 protected void onPause(){if(relay!=null)relay.stop();super.onPause();}
 protected void onDestroy(){if(relay!=null)relay.stop();super.onDestroy();}
}
